#include <bits/stdc++.h>
using namespace std;

const int MD = 998244353;

long long power(long long a, int k) {
    if (k == 0)
        return 1;
    long long p = power(a, k >> 1);
    p = p * p % MD;
    if ((k & 1) == 1)
        p = p * a % MD;
    return p;
}

long long ch(const vector<long long>& ff, const vector<long long>& gg, int n, int k) {
    return ff[n] * gg[k] % MD * gg[n - k] % MD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long k_;
    cin >> n >> k_;
    if (k_ >= n) {
        cout << 0 << "\n";
        return 0;
    }
    int c = n - (int)k_;
    vector<long long> ff(n + n + 1);
    vector<long long> gg(n + n + 1);
    long long f = 1;
    for (int i = 0; i <= n + n; i++) {
        if (i == 0) {
            ff[i] = 1;
        } else {
            ff[i] = (ff[i - 1] * i) % MD;
        }
        gg[i] = power(ff[i], MD - 2);
    }
    long long ans = 0;
    for (int a = 1; a <= c; a++) {
        long long x = power(a, n) * ch(ff, gg, c, a) % MD;
        if ((c - a) % 2 == 0) {
            ans = (ans + x) % MD;
        } else {
            ans = (ans - x + MD) % MD;
        }
    }
    ans = ans * ch(ff, gg, n, c) % MD;
    if (k_ > 0) {
        ans = (ans * 2) % MD;
    }
    cout << ans << "\n";
    return 0;
}

